css:
.venturesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a1f14;
    background: linear-gradient(160deg, #fbf4ea 0%, #f4e7d4 100%);
    border-radius: 18px;
}

.venturesim-container * {
    box-sizing: border-box;
}

.venturesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #6b2d0e 0%, #a8521b 52%, #cf7d2c 100%);
    color: #fff7ec;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(107, 45, 14, 0.30);
}

.venturesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.venturesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f7d9b0;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.venturesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #fbe9d4;
}

.venturesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #7a4014;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.venturesim-period-counter #currentDay,
.venturesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #6b2d0e;
}

.venturesim-round-name {
    background: #f0dcc0;
    color: #6b2d0e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.venturesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9c2a16;
    background: #fbe0d8;
    padding: 4px 12px;
    border-radius: 999px;
}

.venturesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.venturesim-status-card {
    background: #fffdf9;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #ecdcc4;
    box-shadow: 0 4px 14px rgba(107, 45, 14, 0.06);
    border-top: 4px solid #cf7d2c;
}

.venturesim-card-growth { border-top-color: #b7791f; }
.venturesim-card-resilience { border-top-color: #2f7d5b; }
.venturesim-card-capacity { border-top-color: #5b6bb0; }
.venturesim-card-cash { border-top-color: #246b8a; }

.venturesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a6a4a;
}

.venturesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #6b2d0e;
}

.venturesim-card-growth .venturesim-value { color: #b7791f; }
.venturesim-card-resilience .venturesim-value { color: #2f7d5b; }
.venturesim-card-capacity .venturesim-value { color: #5b6bb0; }
.venturesim-card-cash .venturesim-value { color: #246b8a; }

.venturesim-sublabel {
    font-size: 0.76rem;
    color: #9b7c5b;
    line-height: 1.35;
}

.venturesim-resilience-good .venturesim-value { color: #2f7d5b; }
.venturesim-resilience-fragile .venturesim-value { color: #c0392b; }

.venturesim-cash-insolvent { border-top-color: #c0392b; }
.venturesim-cash-insolvent .venturesim-value { color: #c0392b; }

.venturesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #6b2d0e;
    color: #fbe9d4;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.venturesim-budget-bar #equityDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.venturesim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf9;
    border-left: 5px solid #cf7d2c;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(107, 45, 14, 0.05);
}

.venturesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.venturesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #6b2d0e;
    margin-bottom: 6px;
}

.venturesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a382a;
}

.venturesim-briefing-text strong { color: #2f7d5b; }
.venturesim-briefing-text em { color: #9c2a16; font-style: italic; }

.venturesim-controls {
    background: #fffdf9;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ecdcc4;
    box-shadow: 0 4px 14px rgba(107, 45, 14, 0.06);
}

.venturesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #6b2d0e;
    border-bottom: 2px solid #f0e2cd;
    padding-bottom: 8px;
}

.venturesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #5a3c20;
    margin: 14px 0 6px;
}

.venturesim-container select,
.venturesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #dcc4a0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fdf8f0;
    color: #2a1f14;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.venturesim-container select:focus,
.venturesim-container input[type="number"]:focus {
    outline: none;
    border-color: #cf7d2c;
    box-shadow: 0 0 0 3px rgba(207, 125, 44, 0.18);
}

.venturesim-container select option {
    background-color: #fffdf9;
    color: #2a1f14;
}

.venturesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #cf7d2c;
}

.venturesim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #a8521b;
    margin-top: 4px;
}

.venturesim-range-readout span:last-child {
    color: #2f7d5b;
    font-weight: 800;
}

.venturesim-hint {
    font-size: 0.8rem;
    color: #9b7c5b;
    margin-top: 4px;
    line-height: 1.4;
}

.venturesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.venturesim-container .btn-primary {
    background: linear-gradient(135deg, #a8521b 0%, #cf7d2c 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(168, 82, 27, 0.28);
}

.venturesim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.venturesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #dcc4a0;
    color: #8a6a4a;
}

.venturesim-coach {
    background: #2a1f14;
    color: #f4e7d4;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(42, 31, 20, 0.24);
}

.venturesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e0a458;
    margin-bottom: 8px;
}

.venturesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.venturesim-coach-body strong { color: #f3c98a; }
.venturesim-coach-body em { color: #f0a98a; font-style: italic; }

.venturesim-history,
.venturesim-chart {
    background: #fffdf9;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ecdcc4;
    box-shadow: 0 4px 14px rgba(107, 45, 14, 0.06);
}

.venturesim-history h3,
.venturesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #6b2d0e;
}

.venturesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a382a;
}

.venturesim-container table#usfHistoryTable th {
    background: #f5e9d6;
    color: #6b2d0e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ecdcc4;
}

.venturesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f3ead9;
}

.venturesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fdf8f0;
}

.venturesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .venturesim-container {
        padding: 14px;
    }
    .venturesim-header h1 {
        font-size: 1.7rem;
    }
    .venturesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .venturesim-value {
        font-size: 2rem;
    }
    .venturesim-clock {
        margin-left: 0;
    }
    .venturesim-period-counter {
        font-size: 0.88rem;
    }
    .venturesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .venturesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion message (formatCompletionMessage) — self-contained, readable on the white modal */
.venturesim-completion { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #16263a; }
.venturesim-cm-head { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; padding-bottom: 14px; border-bottom: 1px solid rgba(22,38,58,0.15); margin-bottom: 16px; }
.venturesim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #1f6f4a; }
.venturesim-cm-score-max { font-size: 18px; font-weight: 600; color: #45607f; margin-left: 2px; }
.venturesim-cm-grade { font-size: 18px; font-weight: 700; color: #16263a; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.venturesim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .02em; padding: 3px 10px; border-radius: 999px; }
.venturesim-cm-yes { background: rgba(31,111,74,0.16); color: #185a3d; }
.venturesim-cm-no { background: rgba(176,51,37,0.12); color: #b03325; }
.venturesim-cm-warn { background: rgba(180,60,40,0.16); color: #9a2f18; }
.venturesim-cm-metrics { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.venturesim-cm-metric { flex: 1 1 110px; background: #eef1f6; border: 1px solid rgba(22,38,58,0.10); border-radius: 10px; padding: 12px 14px; text-align: center; }
.venturesim-cm-mv { display: block; font-size: 22px; font-weight: 800; color: #16263a; }
.venturesim-cm-ml { display: block; font-size: 12px; font-weight: 600; color: #45607f; margin-top: 2px; }
.venturesim-cm-insights-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: #45607f; margin-bottom: 8px; }
.venturesim-cm-insights { margin: 0; padding-left: 20px; }
.venturesim-cm-insights li { font-size: 14px; line-height: 1.5; color: #22324a; margin-bottom: 8px; }

