(function() {
    'use strict';

    class VentureAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Scaling the Venture`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (GBP, £M unless noted).
            this.START_CASH = 0.45;          // £0.45M buffer
            this.RAMP_NEED = 1.4;            // £1.4M to ramp triple volume
            this.NORTHGATE_VALUE = 6.2;      // £6.2M/yr contract
            this.NEW_LINE = 0.6;             // £0.6M chilled line
            this.OPS_DIRECTOR = 65;          // £65k ops director
            this.LOAN = 1.0;                 // £1.0M bank loan ~9%
            this.EQUITY_CASH = 1.5;          // £1.5M equity
            this.EQUITY_DILUTION = 25;       // 25% for the round

            this.TARGET_RESILIENCE = 60;     // survival-odds target
            this.TARGET_GROWTH = 45;         // a credible scaled outcome

            // Concept truths.
            this.TRUE_CONSTRAINT = `cash`;
            this.TRUE_RISK = `insolvency`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    growth: 5,
                    resilience: 35,
                    capacity: 20,
                    cash: this.START_CASH,
                    equity: 100,
                    pathChosen: `phased`,
                    funded: false,
                    fragile: false,
                    insolvent: false,
                    growthHistory: [5],
                    resilienceHistory: [35],
                    cashHistory: [this.START_CASH],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    constraint: `cash`,
                    risk: `insolvency`,
                    candor: 60,
                    path: `phased`,
                    capex: `newline`,
                    protect: 55,
                    delegate: `targeted`,
                    governance: `rights`,
                    hire: `hire`,
                    standards: 60,
                    instrument: `equity`,
                    timing: `before`,
                    coverage: 100,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const con = document.getElementById(`constraintInput`);
                const risk = document.getElementById(`riskInput`);
                const cand = document.getElementById(`candorInput`);
                if (con) decisions.constraint = con.value;
                if (risk) decisions.risk = risk.value;
                if (cand) decisions.candor = parseInt(cand.value, 10);
                if (!Number.isFinite(decisions.candor) || decisions.candor < 0 || decisions.candor > 100) {
                    warn(`warn_candor_range`); return false;
                }
            } else if (round === 2) {
                const path = document.getElementById(`pathInput`);
                const capex = document.getElementById(`capexInput`);
                const pr = document.getElementById(`protectInput`);
                if (path) decisions.path = path.value;
                if (capex) decisions.capex = capex.value;
                if (pr) decisions.protect = parseInt(pr.value, 10);
                if (!Number.isFinite(decisions.protect) || decisions.protect < 0 || decisions.protect > 100) {
                    warn(`warn_protect_range`); return false;
                }
            } else if (round === 3) {
                const del = document.getElementById(`delegateInput`);
                const gov = document.getElementById(`governanceInput`);
                const hire = document.getElementById(`hireInput`);
                const std = document.getElementById(`standardsInput`);
                if (del) decisions.delegate = del.value;
                if (gov) decisions.governance = gov.value;
                if (hire) decisions.hire = hire.value;
                if (std) decisions.standards = parseInt(std.value, 10);
                if (!Number.isFinite(decisions.standards) || decisions.standards < 0 || decisions.standards > 100) {
                    warn(`warn_standards_range`); return false;
                }
            } else if (round === 4) {
                const ins = document.getElementById(`instrumentInput`);
                const tim = document.getElementById(`timingInput`);
                const cov = document.getElementById(`coverageInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ins) decisions.instrument = ins.value;
                if (tim) decisions.timing = tim.value;
                if (cov) decisions.coverage = parseFloat(cov.value);
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.coverage) || decisions.coverage < 0 || decisions.coverage > 100) {
                    warn(`warn_coverage_range`); return false;
                }
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: growth = scale achieved; resilience = survival odds; capacity = founder
            // decisions freed; cashFlow = £M change to the runway this round.
            let growthDelta = 0, resilienceDelta = 0, capacityDelta = 0, cashFlow = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Round 1 — Diagnose growth readiness & the binding constraints.
                // Cash is the constraint that kills first (Common Error 1: funding-gap blindness).
                if (d.constraint === this.TRUE_CONSTRAINT) {
                    resilienceDelta += 8; coachKey = `coach_r1_cash`;
                } else if (d.constraint === `founder`) {
                    resilienceDelta += 4; capacityDelta += 4; coachKey = `coach_r1_founder`;
                } else if (d.constraint === `concentration`) {
                    resilienceDelta += 5; coachKey = `coach_r1_concentration`;
                } else { // capacity — real but not the first killer
                    resilienceDelta += 3; coachKey = `coach_r1_capacity`;
                }

                // Naming the survival risk. Insolvency matches the cash gap; 'no risk' is fatal.
                if (d.risk === this.TRUE_RISK) {
                    resilienceDelta += 7;
                    if (d.constraint === this.TRUE_CONSTRAINT) coachKey = `coach_r1_sharp`;
                } else if (d.risk === `burnout` || d.risk === `quality`) {
                    resilienceDelta += 3;
                } else { // none
                    resilienceDelta -= 12; coachKey = `coach_r1_norisk`;
                }

                // Candour: willingness to admit the firm is not ready as-is.
                if (d.candor >= 60) { resilienceDelta += 4; capacityDelta += 3; }
                else if (d.candor <= 25) { resilienceDelta -= 6; coachKey = `coach_r1_lowcandor`; }

                summaryKey = (d.constraint === this.TRUE_CONSTRAINT && d.risk === this.TRUE_RISK) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Round 2 — Choose the growth path under cash & resilience constraints.
                // Phased is the disciplined best; full = max growth, max cash & SLA risk;
                // online = resilient but slow; blended = solid middle.
                switch (d.path) {
                    case `phased`:
                        growthDelta += 30; resilienceDelta += 10; cashFlow -= 0.55; coachKey = `coach_r2_phased`; ds.pathChosen = `phased`; break;
                    case `full`:
                        growthDelta += 44; resilienceDelta -= 14; cashFlow -= 1.40; coachKey = `coach_r2_full`; ds.pathChosen = `full`; break;
                    case `online`:
                        growthDelta += 14; resilienceDelta += 12; cashFlow -= 0.20; coachKey = `coach_r2_online`; ds.pathChosen = `online`; break;
                    case `blended`:
                        growthDelta += 36; resilienceDelta += 4; cashFlow -= 0.75; coachKey = `coach_r2_blended`; ds.pathChosen = `blended`; break;
                }

                // Creating capacity for the chosen volume (only matters when taking Northgate volume).
                const takesVolume = (d.path !== `online`);
                switch (d.capex) {
                    case `newline`:
                        resilienceDelta += 6; cashFlow -= this.NEW_LINE; coachKey = (d.path === `phased`) ? `coach_r2_newline` : coachKey; break;
                    case `outsource`:
                        growthDelta += 3; resilienceDelta += (takesVolume ? 2 : 0); cashFlow -= 0.15; break;
                    case `stretch`:
                        if (takesVolume) { resilienceDelta -= 10; coachKey = `coach_r2_stretch`; }
                        else { resilienceDelta -= 2; }
                        break;
                }

                // Concentration protections (Common Error 3: trading resilience for revenue).
                // Matters most when concentration is actually being created (full/blended).
                const concentrationRisk = (d.path === `full`) ? 1.0 : (d.path === `blended`) ? 0.6 : (d.path === `phased`) ? 0.4 : 0.1;
                if (d.protect >= 55) { resilienceDelta += Math.round(10 * concentrationRisk); }
                else if (d.protect <= 25) { resilienceDelta -= Math.round(10 * concentrationRisk); if (concentrationRisk >= 0.6) coachKey = `coach_r2_noprotect`; }

                summaryKey = (d.path === `phased` || d.path === `blended` || d.path === `online`) && d.capex !== `stretch` ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Round 3 — Break the founder bottleneck with governance (Common Errors 2 & 4).
                switch (d.delegate) {
                    case `targeted`:
                        capacityDelta += 26; resilienceDelta += 4; coachKey = `coach_r3_targeted`; break;
                    case `hold`:
                        capacityDelta += 2; resilienceDelta -= 10; growthDelta -= 6; coachKey = `coach_r3_hold`; break;
                    case `all`:
                        capacityDelta += 16; resilienceDelta -= 6; coachKey = `coach_r3_all`; break;
                }

                // Governance: what replaces the founder's judgement (delegation vs abdication).
                switch (d.governance) {
                    case `rights`:
                        resilienceDelta += 10; capacityDelta += 6; coachKey = (d.delegate === `targeted`) ? `coach_r3_governed` : coachKey; break;
                    case `trust`:
                        resilienceDelta -= 2; capacityDelta += 2; break;
                    case `none`:
                        resilienceDelta -= 12; capacityDelta -= 2; coachKey = `coach_r3_nogov`; break;
                }
                // Delegation without governance is abdication — quality slips.
                if (d.delegate === `all` && d.governance === `none`) { resilienceDelta -= 8; coachKey = `coach_r3_abdication`; }

                // Hire-ahead-of-revenue ops director (£65k) frees real capacity.
                switch (d.hire) {
                    case `hire`: capacityDelta += 12; resilienceDelta += 3; cashFlow -= (this.OPS_DIRECTOR / 1000); break;
                    case `later`: capacityDelta += 4; cashFlow -= (this.OPS_DIRECTOR / 2000); break;
                    case `never`: capacityDelta -= 6; resilienceDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_nohire` : coachKey; break;
                }

                // Standards Priya must never delegate (recipe/brand) — protect them.
                if (d.standards >= 55) { resilienceDelta += 5; }
                else if (d.standards <= 25) { resilienceDelta -= 6; if (coachKey === `coach_default`) coachKey = `coach_r3_nostandards`; }

                summaryKey = (d.delegate === `targeted` && d.governance === `rights`) ? `sum_r3_good` : (d.delegate === `hold` ? `sum_r3_bottleneck` : `sum_r3_weak`);
            } else if (round === 4) {
                // Round 4 — Time & structure the financing move (Common Error 5).
                // Cash injected this round depends on instrument and coverage of the £1.4M gap.
                const coverageFrac = d.coverage / 100;
                let raised = 0;
                switch (d.instrument) {
                    case `loan`:
                        raised = this.LOAN; resilienceDelta += 3; growthDelta += 4; coachKey = `coach_r4_loan`; break;
                    case `equity`:
                        raised = this.EQUITY_CASH; resilienceDelta += 9; growthDelta += 6;
                        ds.equity = Math.max(0, ds.equity - this.EQUITY_DILUTION); ds.funded = true; coachKey = `coach_r4_equity`; break;
                    case `blend`:
                        raised = 0.9; resilienceDelta += 6; growthDelta += 4; coachKey = `coach_r4_blend`; break;
                    case `bootstrap`:
                        raised = 0.25; resilienceDelta -= 6; growthDelta -= 4; coachKey = `coach_r4_bootstrap`; break;
                }
                // Only the covered fraction of the need is actually bridged.
                cashFlow += raised * coverageFrac;

                // Timing the raise against valuation and cash need.
                switch (d.timing) {
                    case `before`:
                        resilienceDelta += 5; coachKey = (d.instrument === `equity` || d.instrument === `blend`) ? `coach_r4_before` : coachKey; break;
                    case `proof`:
                        // Raising after traction is shrewd ONLY if the cash can survive the gap meanwhile.
                        growthDelta += 3;
                        if (ds.cash + cashFlow < 0.05) { resilienceDelta -= 10; coachKey = `coach_r4_proof_risky`; }
                        else { resilienceDelta += 3; coachKey = `coach_r4_proof`; }
                        break;
                    case `late`:
                        resilienceDelta -= 12; coachKey = `coach_r4_late`; break;
                }
                // Equity raised too early & cheaply when growth is unproven (Common Error 6).
                if (d.instrument === `equity` && d.timing === `before` && ds.growth < 25) {
                    resilienceDelta -= 4; coachKey = `coach_r4_earlyequity`;
                }

                // Coverage of the funding gap.
                if (d.coverage >= 90) { resilienceDelta += 5; }
                else if (d.coverage <= 40) { resilienceDelta -= 8; if (coachKey === `coach_default`) coachKey = `coach_r4_undercover`; }

                // Conviction nudges resilience.
                resilienceDelta += Math.round((d.conviction - 60) / 10);

                summaryKey = (d.coverage >= 90 && d.timing !== `late` && d.instrument !== `bootstrap`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply cash flow to the runway.
            ds.cash = Math.round((ds.cash + cashFlow) * 100) / 100;
            if (ds.cash < 0) ds.insolvent = true;

            // A negative runway crushes survival odds — profitable growth that runs out of cash.
            if (ds.cash < 0) {
                resilienceDelta -= Math.min(30, Math.round(Math.abs(ds.cash) * 18));
            } else if (ds.cash < 0.1 && round >= 2) {
                resilienceDelta -= 4;
            }

            // Apply meter deltas with headroom (0–100).
            ds.growth = Math.max(0, Math.min(100, ds.growth + growthDelta));
            ds.resilience = Math.max(0, Math.min(100, ds.resilience + resilienceDelta));
            ds.capacity = Math.max(0, Math.min(100, ds.capacity + capacityDelta));

            // Fragile flag: scaled hard but survival odds are weak.
            if (ds.growth >= 40 && ds.resilience < 40) ds.fragile = true;

            ds.growthHistory.push(Math.round(ds.growth));
            ds.resilienceHistory.push(Math.round(ds.resilience));
            ds.cashHistory.push(Math.round(ds.cash * 100) / 100);

            // v1.1.0: publish composite (0-100) to the reporting/grading layer every period.
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                growth: Math.round(ds.growth),
                growthDelta: Math.round(growthDelta),
                resilience: Math.round(ds.resilience),
                resilienceDelta: Math.round(resilienceDelta),
                capacity: Math.round(ds.capacity),
                capacityDelta: Math.round(capacityDelta),
                cash: Math.round(ds.cash * 100) / 100,
                cashFlow: Math.round(cashFlow * 100) / 100,
                equity: Math.round(ds.equity),
                insolvent: ds.insolvent,
                fragile: ds.fragile,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

