        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.growthHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                ventureChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.growthHistory },
                        { data: ds.resilienceHistory },
                        { data: ds.cashHistory }
                    ]
                }
            };
        }

        // Composite (0-100) VERBATIM from v1.0.0 getPerformanceSummary (incl. solvency bonus);
        // written to domainState.performance.overallScore each period for the reporting layer.
        _composite(ds) {
            var growth = Math.round(ds.growth || 0);
            var resilience = Math.round(ds.resilience || 0);
            var capacity = Math.round(ds.capacity || 0);
            var cash = Math.round((ds.cash || 0) * 100) / 100;
            var solvent = cash >= 0;
            return Math.round(Math.min(100, growth) * 0.30 + resilience * 0.40 + capacity * 0.20 + (solvent ? 10 : 0));
        }

        _cl(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return fallback;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const growth = Math.round(ds.growth);
            const resilience = Math.round(ds.resilience);
            const capacity = Math.round(ds.capacity);
            const cash = Math.round(ds.cash * 100) / 100;

            const solvent = cash >= 0;
            const survives = resilience >= this.TARGET_RESILIENCE && solvent;
            const scaled = growth >= this.TARGET_GROWTH;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_stalled`;
            if (!solvent) performanceKey = `grade_insolvent`;
            else if (scaled && survives && composite >= 68) performanceKey = `grade_scaled`;
            else if (survives && growth >= 35) performanceKey = `grade_disciplined`;
            else if (scaled && resilience < 45) performanceKey = `grade_fragile`;
            else if (resilience >= this.TARGET_RESILIENCE) performanceKey = `grade_safe`;
            const performance = T(performanceKey);

            const insights = [];
            if (!solvent) insights.push(window.mySimulation.t(`insight_insolvent`));
            else if (scaled && survives) insights.push(window.mySimulation.t(`insight_scaled`));
            else if (scaled && resilience < 45) insights.push(window.mySimulation.t(`insight_fragile`));
            else if (survives) insights.push(window.mySimulation.t(`insight_disciplined`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (capacity < 45) insights.push(window.mySimulation.t(`insight_bottleneck`));
            if (ds.fragile) insights.push(window.mySimulation.t(`insight_concentration`));
            if (ds.equity < 100 && survives) insights.push(window.mySimulation.t(`insight_equity`));
            if (scaled && survives && capacity >= 60) insights.push(window.mySimulation.t(`insight_transition`));

            return {
                growth: growth,
                resilience: resilience,
                capacity: capacity,
                cash: cash,
                solvent: solvent,
                survives: survives,
                scaled: scaled,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var money = '\u00a3' + (Math.round((s.cash || 0) * 10) / 10) + 'M';
            var ok = !!s.survives;
            var badge = ok
                ? '<span class="venturesim-cm-badge venturesim-cm-yes">' + T('cm_met') + '</span>'
                : '<span class="venturesim-cm-badge venturesim-cm-no">' + T('cm_missed') + '</span>';
            var failBadge = (!s.solvent)
                ? '<span class="venturesim-cm-badge venturesim-cm-warn">' + T('cm_failstate_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="venturesim-cm-metric"><span class="venturesim-cm-mv">' + Math.round(s.growth || 0) + '</span><span class="venturesim-cm-ml">' + T('cm_m_growth') + '</span></div>'
                + '<div class="venturesim-cm-metric"><span class="venturesim-cm-mv">' + Math.round(s.resilience || 0) + '</span><span class="venturesim-cm-ml">' + T('cm_m_resilience') + '</span></div>'
                + '<div class="venturesim-cm-metric"><span class="venturesim-cm-mv">' + Math.round(s.capacity || 0) + '</span><span class="venturesim-cm-ml">' + T('cm_m_capacity') + '</span></div>'
                + '<div class="venturesim-cm-metric"><span class="venturesim-cm-mv">' + money + '</span><span class="venturesim-cm-ml">' + T('cm_m_cash') + '</span></div>';
            return ''
                + '<div class="venturesim-completion">'
                +   '<div class="venturesim-cm-head">'
                +     '<div class="venturesim-cm-score">' + score + '<span class="venturesim-cm-score-max">/100</span></div>'
                +     '<div class="venturesim-cm-grade">' + grade + ' ' + badge + failBadge + '</div>'
                +   '</div>'
                +   '<div class="venturesim-cm-metrics">' + metrics + '</div>'
                +   '<div class="venturesim-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="venturesim-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.cash < 0) return window.mySimulation.t(`hint_insolvent`);
            if (ds.fragile) return window.mySimulation.t(`hint_fragile`);
            if (ds.capacity < 35 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_bottleneck`);
            if (ds.resilience < 35) return window.mySimulation.t(`hint_resilience`);
            if (ds.cash < 0.1 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_cash`);
            if (ds.growth >= this.TARGET_GROWTH && ds.resilience >= this.TARGET_RESILIENCE) return window.mySimulation.t(`hint_strong`);
            return null;
        }

